export function bindBoard(s: State, onResize: () => void): cg.Unbind {
  const boardEl = s.dom.elements.board;

  let unbind: cg.Unbind | undefined;
  if ('ResizeObserver' in window) unbind = (new ResizeObserver(onResize).observe(...)); 
```

